import{y as t,b as o,c as a,X as r}from"./chunks/vue.Bn9cO5I3.js";import"./app.tjc9Wtrh.js";import"./chunks/mermaid.DvhSlOLG.js";const g=JSON.parse('{"title":"Economic Governance & Token ROI Modeling (WP-5003)","description":"","frontmatter":{},"headers":[],"relativePath":"reference/ECONOMIC_GOVERNANCE_DEPTH.md","filePath":"reference/ECONOMIC_GOVERNANCE_DEPTH.md","lastUpdated":1771753292000}'),n={name:"reference/ECONOMIC_GOVERNANCE_DEPTH.md"};function i(s,e,d,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="economic-governance-token-roi-modeling-wp-5003" tabindex="-1">Economic Governance &amp; Token ROI Modeling (WP-5003) <a class="header-anchor" href="#economic-governance-token-roi-modeling-wp-5003" aria-label="Permalink to &quot;Economic Governance &amp; Token ROI Modeling (WP-5003)&quot;">​</a></h1><p>This document defines the depth for <strong>Economic Governance</strong> within <code>thegent</code>, focusing on token unit economics, cost attribution, and ROI-driven routing.</p><h2 id="_1-token-unit-economics-cost-attribution" tabindex="-1">1. Token Unit Economics &amp; Cost Attribution <a class="header-anchor" href="#_1-token-unit-economics-cost-attribution" aria-label="Permalink to &quot;1. Token Unit Economics &amp; Cost Attribution&quot;">​</a></h2><p><code>thegent</code> treats AI compute as a finite economic resource. Every <code>RunMeta</code> and <code>OrchestrationEvent</code> must attribute costs to specific project entities.</p><h3 id="_1-1-attribution-hierarchy" tabindex="-1">1.1 Attribution Hierarchy <a class="header-anchor" href="#_1-1-attribution-hierarchy" aria-label="Permalink to &quot;1.1 Attribution Hierarchy&quot;">​</a></h3><p>Costs are rolled up in a 3-tier hierarchy:</p><ol><li>undefined<strong>Work Package (WP)</strong>: The direct cost to complete a specific task (e.g., <code>WP-3002</code>).</li><li>undefined<strong>Batch/Epic</strong>: The cumulative cost of a sequential batch of agents.</li><li>undefined<strong>Session/Project</strong>: The total burn rate for the current user or project.</li></ol><h3 id="_1-2-resource-metering-wp-5003" tabindex="-1">1.2 Resource Metering (WP-5003) <a class="header-anchor" href="#_1-2-resource-metering-wp-5003" aria-label="Permalink to &quot;1.2 Resource Metering (WP-5003)&quot;">​</a></h3><p>The <code>thegent</code> core tracks:</p><ul><li><code>tokens_in</code>: Prompt tokens.</li><li><code>tokens_out</code>: Completion tokens.</li><li><code>cost_usd</code>: Calculated based on the provider&#39;s specific rate (scraped via <code>models/scrapers.py</code>).</li><li><code>compute_s</code>: Wall-clock execution time.</li></ul><h2 id="_2-roi-driven-routing-task-scoring" tabindex="-1">2. ROI-Driven Routing &amp; Task Scoring <a class="header-anchor" href="#_2-roi-driven-routing-task-scoring" aria-label="Permalink to &quot;2. ROI-Driven Routing &amp; Task Scoring&quot;">​</a></h2><p>Not all tasks justify the use of a flagship model (e.g., GPT-4o, Claude 3.5 Sonnet). <code>thegent</code> uses <strong>ROI Scoring</strong> to determine the appropriate model tier.</p><h3 id="_2-1-task-value-scoring" tabindex="-1">2.1 Task Value Scoring <a class="header-anchor" href="#_2-1-task-value-scoring" aria-label="Permalink to &quot;2.1 Task Value Scoring&quot;">​</a></h3><p>Tasks in the <strong>Unified Work Stream</strong> are assigned a <code>Value_Score</code> (0.0–1.0):</p><ul><li>undefined<strong>High Value (0.8–1.0)</strong>: Final verification, complex architecture, critical security fixes.</li><li>undefined<strong>Medium Value (0.4–0.7)</strong>: Implementation, unit testing, documentation synthesis.</li><li>undefined<strong>Low Value (0.0–0.3)</strong>: Initial research (eXplore), style fixes, boilerplate generation.</li></ul><h3 id="_2-2-roi-thresholds" tabindex="-1">2.2 ROI Thresholds <a class="header-anchor" href="#_2-2-roi-thresholds" aria-label="Permalink to &quot;2.2 ROI Thresholds&quot;">​</a></h3><p>The router applies the following logic:</p><ul><li><code>ROI = (Value_Score * Expected_Accuracy) / Cost</code></li><li>The <code>thegent</code> orchestrator selects the provider on the <strong>Pareto Front</strong> that maximizes ROI within the current budget.</li></ul><h2 id="_3-budget-caps-hard-stops-wp-5003" tabindex="-1">3. Budget Caps &amp; Hard Stops (WP-5003) <a class="header-anchor" href="#_3-budget-caps-hard-stops-wp-5003" aria-label="Permalink to &quot;3. Budget Caps &amp; Hard Stops (WP-5003)&quot;">​</a></h2><p>To prevent runaway loops (e.g., recursive research), <code>thegent</code> implements multi-level budget gates:</p><table tabindex="0"><thead><tr><th>Level</th><th>Action</th><th>Rationale</th></tr></thead><tbody><tr><td>undefined<strong>Warning (80%)</strong>undefined</td><td>Notify Cockpit &amp; Alert Log.</td><td>Operator awareness.</td></tr><tr><td>undefined<strong>Soft Cap (95%)</strong>undefined</td><td>Route to cheaper models only.</td><td>Degraded performance to save budget.</td></tr><tr><td>undefined<strong>Hard Stop (100%)</strong>undefined</td><td>Terminate run &amp; pause session.</td><td>Prevent financial overburn.</td></tr></tbody></table><h2 id="_4-economic-reporting" tabindex="-1">4. Economic Reporting <a class="header-anchor" href="#_4-economic-reporting" aria-label="Permalink to &quot;4. Economic Reporting&quot;">​</a></h2><p>The <strong>Operator Cockpit</strong> provides a real-time &quot;Burn Rate&quot; visualization, showing:</p><ul><li>undefined<strong>MTD Spend</strong> vs. <strong>Monthly Budget</strong>.</li><li>undefined<strong>Project ROI</strong>: Estimated value delivered vs. tokens consumed.</li><li>undefined<strong>Top 5 Costly WPs</strong>: Identifying bottlenecks for model-tier optimization.</li></ul><hr><p><em>Cross-ref: <a href="./PARETO_ROUTING_DESIGN.html">PARETO_ROUTING_DESIGN.md</a> | <a href="./../plans/05-ARCHITECTURE.html">05-ARCHITECTURE.md</a></em></p><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../reference/WORK_STREAM.html">WORK_STREAM.md</a> — canonical backlog</li><li><a href="./../plans/00-MASTER-INDEX.html">00-MASTER-INDEX.md</a> — plan index</li></ul><hr><h2 id="extension-summary" tabindex="-1">EXTENSION_SUMMARY <a class="header-anchor" href="#extension-summary" aria-label="Permalink to &quot;EXTENSION_SUMMARY&quot;">​</a></h2><p>undefined<strong>Extended on:</strong> 2026-02-17 undefined<strong>Extended by:</strong> Claude Code</p><h3 id="changes-made" tabindex="-1">Changes Made <a class="header-anchor" href="#changes-made" aria-label="Permalink to &quot;Changes Made&quot;">​</a></h3><ol><li>Added practical implementation patterns</li><li>Added configuration examples</li><li>Enhanced cross-references to related documentation</li></ol><h3 id="cross-references-added" tabindex="-1">Cross-References Added <a class="header-anchor" href="#cross-references-added" aria-label="Permalink to &quot;Cross-References Added&quot;">​</a></h3><ul><li>Related research and implementation guides</li><li>WORK_STREAM.md for tracking</li></ul><h3 id="practical-additions" tabindex="-1">Practical Additions <a class="header-anchor" href="#practical-additions" aria-label="Permalink to &quot;Practical Additions&quot;">​</a></h3><ul><li>Implementation templates</li><li>Configuration examples</li><li>Best practices</li></ul>',38)])])}const f=t(n,[["render",i]]);export{g as __pageData,f as default};
